%macro mfv_existfile(filepath
)/*/STORE SOURCE*/;

  %mf_abort(
    iftrue=(&syscc ne 0),
    msg=Cannot enter mfv_existfile.sas with syscc=&syscc
  )

  %local fref rc path name;
  %let fref=%mf_getuniquefileref();
  %let name=%scan(&filepath,-1,/);
  %let path=%substr(&filepath,1,%length(&filepath)-%length(&name)-1);

  %if %sysfunc(filename(fref,,filesrvc,folderPath="&path" filename="&name"))=0
  %then %do;
    %sysfunc(fexist(&fref))
    %let rc=%sysfunc(filename(fref));
  %end;
  %else %do;
    0
    %let syscc=0;
  %end;

%mend mfv_existfile;


%macro mp_init(prefix=SASJS
)/*/STORE SOURCE*/;

%if %symexist(SASJS_PREFIX) %then %return;  /* only run once */

%global
  SASJS_PREFIX       /* the ONLY hard-coded global macro variable in SASjs    */
  &prefix.PROCESSMODE &prefix._STPSRV_HEADER_LOC /* SASjs server specific vars*/
  &prefix._FUNCTIONS /* used in mcf_init() to track core function compilation */
  &prefix._INIT_NUM  /* initialisation time as numeric                        */
  &prefix._INIT_DTTM /* initialisation time in E8601DT26.6 format             */
  &prefix.WORK       /* avoid typing %sysfunc(pathname(work)) every time      */
  &prefix.PROCESSMODE
  &prefix._STPSRV_HEADER_LOC
;
%let sasjs_prefix=&prefix;

data _null_;
  dttm=datetime();
  call symputx("&sasjs_prefix._init_num",dttm,'g');
  call symputx("&sasjs_prefix._init_dttm",put(dttm,E8601DT26.6),'g');
  call symputx("&sasjs_prefix.work",pathname('WORK'),'g');
run;

options
  compress=CHAR           /* default is none so ensure we have something!   */
  datastmtchk=ALLKEYWORDS /* protection from overwriting input datasets     */
  errorcheck=STRICT       /* catch errs in libname/filename statements      */
  fmterr                  /* ensure err when a format cannot be found       */
  mergenoby=%str(ERR)OR   /* throw err when a merge has no BY variables     */
  missing=.               /* changing this can cause hard to detect errs    */
  noquotelenmax           /* avoid warnings for long strings                */
  noreplace               /* avoid overwriting permanent datasets           */
  ps=max                  /* reduce log size slightly                       */
  ls=max                  /* reduce log even more and avoid word truncation */
  validmemname=COMPATIBLE /* avoid special characters etc in table names    */
  validvarname=V7         /* avoid special characters etc in variable names */
  varinitchk=%str(ERR)OR  /* avoid data mistakes from variable name typos   */
  varlenchk=%str(ERR)OR   /* fail hard if truncation (data loss) can result */
%if "%substr(&sysver,1,1)" ne "4" and "%substr(&sysver,1,1)" ne "5" %then %do;
  noautocorrect           /* disallow misspelled procedure names            */
  dsoptions=note2err      /* undocumented - convert bad NOTEs to ERRs       */
                          /* turn off with dsoptions=nonote2err             */
%end;
;

%mend mp_init;




%macro mf_getuniquename(prefix=MC);
&prefix.%substr(%sysfunc(compress(%sysfunc(uuidgen()),-)),1,32-%length(&prefix))
%mend mf_getuniquename;


%macro ms_getfile(driveloc
    ,outref=msgetfil
    ,mdebug=0
  );

/* use the recfm in a separate fileref to avoid issues with subsequent reads */
%local binaryfref floc headref;
%let binaryfref=%mf_getuniquefileref();
%let headref=%mf_getuniquefileref();
%let floc=%sysfunc(pathname(work))/%mf_getuniquename().txt;
filename &outref "&floc" lrecl=32767;
filename &binaryfref "&floc" recfm=n;

data _null_;
  file &headref lrecl=1000;
  infile "&_sasjs_tokenfile" lrecl=1000;
  input;
  put _infile_;
run;

proc http method='GET' out=&binaryfref headerin=&headref
  url="&_sasjs_apiserverurl/SASjsApi/drive/file?_filePath=&driveloc";
%if &mdebug=1 %then %do;
  debug level=2;
%end;
run;

filename &binaryfref clear;
filename &headref clear;

%mend ms_getfile;


%macro md_init();

%global md_rootdir apploc _program _debug sasjs_mdebug;

/* strict mode */
%mp_init()

%let sasjs_mdebug=0;

/* find apploc */
%let apploc=%mf_getapploc(&_program);

/* fetch input tables (work.* datasets from the adapter) - the %webout
  macro is auto-packaged into services by the sasjs compiler */
%webout(FETCH)

/* configure lrecl */
options lrecl=32767;

/* get Macro Dash settings (a plain file under the apploc, written by the
  configure service).  Missing file = unconfigured - not an error. */
%if %length(&md_rootdir)>0 %then %do;
  /* nothing - the settings have already been made (eg autoexec) */
%end;
%else %if %mf_getplatform()=SASVIYA %then %do;
  %if %mfv_existfile(&apploc/settings.sas)=1 %then %do;
    %put &sysmacroname: fetching remote settings;
    filename mdconfg filesrvc folderpath="&apploc" filename="settings.sas";
    %inc mdconfg /source2;
  %end;
%end;
%else %if %mf_getplatform()=SASJS %then %do;
  %put &sysmacroname: fetching remote settings;
  %ms_getfile(&apploc/settings.sas, outref=mdconfg)
  /* a missing file returns a JSON error body - only %inc real settings */
  %local md_valid; %let md_valid=0;
  data _null_;
    infile mdconfg obs=10 end=eof;
    input;
    if index(_infile_,'%let md_rootdir') then call symputx('md_valid',1);
  run;
  %if &md_valid=1 %then %do;
    %inc mdconfg /source2;
  %end;
%end;
%else %if %mf_getplatform()=SAS9 or %mf_getplatform()=SASMETA %then %do;
  /* SAS 9 has no file concept - settings.sas is a type 2 STP whose source
  code IS the settings.  Fetch it with mm_getstpcode; a missing STP is
  not an error (unconfigured app). */
  %put &sysmacroname: fetching remote settings (SAS 9 STP);
  filename mdconfg temp lrecl=32767;
  %mm_getstpcode(tree=&apploc,name=settings,outref=mdconfg)
  %if &syscc=0 %then %do;
    %local md_valid; %let md_valid=0;
    data _null_;
      infile mdconfg obs=10 end=eof;
      input;
      if index(_infile_,'%let md_rootdir') then call symputx('md_valid',1);
    run;
    %if &md_valid=1 %then %do;
      %inc mdconfg /source2;
    %end;
  %end;
  filename mdconfg clear;
%end;

/* when configured, assign the results library */
%if %length(&md_rootdir)>0 %then %do;
  %mf_mkdir(&md_rootdir)
  libname SB "&md_rootdir";
%end;

%mend md_init;



%macro mf_existds(libds
)/*/STORE SOURCE*/;

  %if %sysfunc(exist(&libds)) ne 1 & %sysfunc(exist(&libds,VIEW)) ne 1 %then 0;
  %else 1;

%mend mf_existds;



%macro mf_getuser(
)/*/STORE SOURCE*/;
  %local user;

  %if %symexist(_sasjs_username) %then %let user=&_sasjs_username;
  %else %if %symexist(SYS_COMPUTE_SESSION_OWNER) %then %do;
    %let user=&SYS_COMPUTE_SESSION_OWNER;
  %end;
  %else %if %symexist(_metaperson) %then %do;
    %if %length(&_metaperson)=0 %then %let user=&sysuserid;
    /* sometimes SAS will add @domain extension - remove for consistency */
    /* but be sure to quote in case of usernames with commas */
    %else %let user=%unquote(%scan(%quote(&_metaperson),1,@));
  %end;
  %else %let user=&sysuserid;

  %quote(&user)

%mend mf_getuser;

* SAS Macros end;
* SAS Includes start;

* SAS Includes end;
* Binary Files start;

* Binary Files end;


* Service start;


%md_init()

%mp_abort(iftrue= (%length(&md_rootdir)=0)
  ,mac=&_program
  ,msg=%str(Macro Dash is not configured - no results folder)
)

%mp_abort(iftrue= (%mf_existds(work.savescore)=0)
  ,mac=&_program
  ,msg=%str(No savescore input table provided)
)

data newscore;
  length name $12 time 8 score 8 amps 8 done 8 submitted 8;
  set work.savescore(rename=(time=tm score=sc amps=am done=dn));
  /* multiplayer (backend) mode: the name is the logged-in SAS user, not
  a client-supplied initials string - the frontend sends no name and
  we grab it server-side with %mf_getuser().  Local mode never reaches
  this service (no backend). */
  if missing(name) then name=upcase("%mf_getuser()");
  else name=upcase(substr(name,1,12));
  time=tm;
  score=sc;
  amps=am;
  done=min(max(coalesce(dn,0),0),1);
  submitted=datetime();
  keep name time score amps done submitted;
run;

data _null_;
  set newscore;
  call symputx('md_time',time);
  call symputx('md_score',score);
  call symputx('md_done',done);
  call symputx('md_submitted',submitted);
run;

%macro md_append();
%if %mf_existds(sb.scores) %then %do;
  proc append base=sb.scores data=newscore;
  run;
%end;
%else %do;
  data sb.scores;
    set newscore;
  run;
%end;
%mend md_append;
%md_append()

/* rank of this run: finishers rank by time (then score); DNFs rank after
  every finisher, most-recent first */
proc sql noprint;
  %if &md_done=1 %then %do;
    select count(*) into :rank trimmed
    from sb.scores
    where done=1
      and (time < &md_time
        or (time = &md_time and score > &md_score));
  %end;
  %else %do;
    select count(*) into :rank trimmed
    from sb.scores
    where done=1
      or (done=0 and submitted > &md_submitted);
  %end;
quit;

%let rank=%eval(&rank+1);

proc sql;
  create table scores as
  select name, time, score, amps, done,
    monotonic() as rank
  from sb.scores
  order by done desc, time, score desc, submitted desc
  ;
quit;

data scores;
  set scores(obs=10);
run;

data result;
  length rank 8;
  rank=&rank;
  output;
run;

%webout(OPEN)
%webout(OBJ,scores)
%webout(OBJ,result)
%webout(CLOSE)

* Service end;

/* Macro Dash - WebAudio sound (all synthesized, no assets => CSP-safe).
 * AudioContext starts on first user gesture (autoplay policy). */
(function () {
  "use strict";

  var ctx = null;

  function ensure() {
    if (!ctx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ctx = new AC();
    }
    if (ctx.state === "suspended") ctx.resume();
    return ctx;
  }

  function beep(freq, dur, type, gain) {
    var c = ensure();
    if (!c) return;
    var o = c.createOscillator();
    var g = c.createGain();
    o.type = type || "square";
    o.frequency.value = freq;
    g.gain.setValueAtTime(gain || 0.08, c.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + dur);
    o.connect(g);
    g.connect(c.destination);
    o.start();
    o.stop(c.currentTime + dur);
  }

  // ---- funky music loop (E-minor funk: bass, kick, snare, hats, lead) ----
  var BPM = 112;
  var STEP = 60 / BPM / 4; // 16th note
  var musicTimer = null;
  var nextStep = 0;
  var stepTime = 0;

  // 2-bar loop, 32 sixteenths. Bass: E E G E | A G E D (funk walk)
  var BASS = [
    41.2, 0, 41.2, 0, 49, 0, 41.2, 0, 41.2, 0, 55, 49, 41.2, 0, 36.7, 0,
    55, 0, 49, 0, 41.2, 0, 49, 0, 36.7, 0, 41.2, 0, 49, 0, 55, 61.7
  ];
  // lead riff (sparse, funky) - E5 pentatonic-ish
  var LEAD = [
    0, 0, 659, 0, 0, 587, 0, 0, 0, 0, 523, 587, 0, 0, 0, 0,
    0, 0, 784, 0, 0, 659, 0, 587, 0, 523, 0, 587, 0, 0, 0
  ];

  var noiseBuf = null;
  function noise(c) {
    if (!noiseBuf) {
      noiseBuf = c.createBuffer(1, c.sampleRate * 0.2, c.sampleRate);
      var d = noiseBuf.getChannelData(0);
      for (var i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    }
    var src = c.createBufferSource();
    src.buffer = noiseBuf;
    return src;
  }

  function playStep(step, t) {
    var c = ctx;
    // kick: beats 0 & 2 of each bar (steps 0,8,16,24)
    if (step % 8 === 0) {
      var k = c.createOscillator(), kg = c.createGain();
      k.type = "sine";
      k.frequency.setValueAtTime(120, t);
      k.frequency.exponentialRampToValueAtTime(40, t + 0.12);
      kg.gain.setValueAtTime(0.25, t);
      kg.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
      k.connect(kg); kg.connect(c.destination);
      k.start(t); k.stop(t + 0.16);
    }
    // snare: beats 1 & 3 (steps 4,12,20,28)
    if (step % 8 === 4) {
      var s = noise(c), sg = c.createGain(), sf = c.createBiquadFilter();
      sf.type = "highpass"; sf.frequency.value = 1500;
      sg.gain.setValueAtTime(0.15, t);
      sg.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
      s.connect(sf); sf.connect(sg); sg.connect(c.destination);
      s.start(t); s.stop(t + 0.12);
    }
    // hats: offbeat 8ths
    if (step % 2 === 1) {
      var h = noise(c), hg = c.createGain(), hf = c.createBiquadFilter();
      hf.type = "highpass"; hf.frequency.value = 7000;
      hg.gain.setValueAtTime(0.05, t);
      hg.gain.exponentialRampToValueAtTime(0.001, t + 0.04);
      h.connect(hf); hf.connect(hg); hg.connect(c.destination);
      h.start(t); h.stop(t + 0.05);
    }
    // bass
    var bf = BASS[step];
    if (bf) {
      var b = c.createOscillator(), bg = c.createGain(), blf = c.createBiquadFilter();
      b.type = "sawtooth";
      b.frequency.value = bf;
      blf.type = "lowpass"; blf.frequency.value = 400;
      bg.gain.setValueAtTime(0.2, t);
      bg.gain.exponentialRampToValueAtTime(0.001, t + STEP * 0.9);
      b.connect(blf); blf.connect(bg); bg.connect(c.destination);
      b.start(t); b.stop(t + STEP);
    }
    // lead
    var lf = LEAD[step];
    if (lf) {
      var l = c.createOscillator(), lg = c.createGain();
      l.type = "square";
      l.frequency.value = lf;
      lg.gain.setValueAtTime(0.07, t);
      lg.gain.exponentialRampToValueAtTime(0.001, t + STEP * 1.8);
      l.connect(lg); lg.connect(c.destination);
      l.start(t); l.stop(t + STEP * 2);
    }
  }

  function startMusic() {
    var c = ensure();
    if (!c || musicTimer) return;
    nextStep = 0;
    stepTime = c.currentTime + 0.1;
    musicTimer = setInterval(function () {
      // lookahead scheduler (schedule ~0.15s ahead)
      while (stepTime < c.currentTime + 0.15) {
        playStep(nextStep, stepTime);
        stepTime += STEP;
        nextStep = (nextStep + 1) % 32;
      }
    }, 40);
  }

  function stopMusic() {
    if (musicTimer) { clearInterval(musicTimer); musicTimer = null; }
  }

  window.MACRODASH_AUDIO = {
    unlock: ensure,
    startMusic: startMusic,
    stopMusic: stopMusic,
    state: function () { return ctx ? ctx.state : "off"; },
    jingle: function () { // title screen: %LET %LET %LET arpeggio
      [330, 415, 494, 659, 494, 415].forEach(function (f, i) {
        setTimeout(function () { beep(f, 0.14, "triangle", 0.09); }, i * 90);
      });
    },
    jump: function () { beep(440, 0.12, "square", 0.12); },
    collect: function () { beep(880, 0.08, "sine"); beep(1320, 0.12, "sine", 0.05); },
    hurt: function () { beep(160, 0.25, "sawtooth", 0.12); },
    powerup: function () { [523, 659, 784, 1047].forEach(function (f, i) {
      setTimeout(function () { beep(f, 0.1, "square", 0.06); }, i * 70);
    }); },
    win: function () { [392, 523, 659, 784].forEach(function (f, i) {
      setTimeout(function () { beep(f, 0.15, "triangle", 0.08); }, i * 120);
    }); }
  };
})();

/* Macro Dash - backend client via @sasjs/adapter (UMD bundle: src/sasjs.js,
 * copied from node_modules by `npm run prepare`).
 *
 * Config comes from the hidden <sasjs> element in index.html (same pattern
 * as the sasjs seed app).  When the game is streamed by SAS itself, no
 * serverUrl is needed - same-origin requests just work, which keeps us
 * CSP-safe (default-src 'self').
 *
 * Adapter contract: request() inputs are TABLES (arrays of objects) which
 * arrive in SAS as work datasets.  Outputs come back on response.result,
 * with UPPERCASE column names.  Any failure (offline dev, unconfigured
 * backend) degrades gracefully to localStorage-only mode.
 */
(function () {
  "use strict";

  var el = document.querySelector("sasjs");
  var serverType = (el && el.getAttribute("serverType")) || "SASJS";
  var forceViya = false; // test-only: render the Viya configurator locally

  /* debug ON on every platform: the adapter captures the per-request SAS
     log (getSasRequests()[n].logFile) which the frontend surfaces as a
     download link.  As with every SASjs app, the initial configure step
     ships debug ON so any setup failure (folder permissions, context
     choice, stamp not landing) can be triaged fast from the downloaded log.
     On Viya this requires a non-JES-web apiMode (compute or jes) - the JES
     web path wraps webout JSON in an HTML page when _debug=128, which the
     adapter cannot parse, so JES web is avoided for now. */
  var debug = true;

  /* Viya compute context, chosen on the setup screen (persisted) */
  var contextName = null;
  try { contextName = localStorage.getItem("macrodash_context"); } catch (e) {}

  /* three-state attribute: "true" -> true, "false" -> false, else undefined */
  function attr3(name) {
    var v = el && el.getAttribute(name);
    return v === "true" ? true : v === "false" ? false : undefined;
  }

  /* Viya execution options (setup screen; persisted in localStorage, with
     the attributes stamped into this page by the configure service as the
     shared default).  Adapter contract (see @sasjs/adapter README) -
     useComputeApi is THREE-state:
       - null/undefined = JES web app (most reliable, slowest); the ONLY
         mode where runAsTask applies (adds _EXECUTIONTASKS=true)
       - false          = JES API (jobs visible in Environment Manager)
       - true           = Compute API (fastest, not in Env Manager)
     We model this as apiMode: "web" | "jes" | "compute". */
  function apiModeFromAttr() {
    var v = attr3("useComputeApi");
    return v === true ? "compute" : v === false ? "jes" : "web";
  }
  var apiMode = apiModeFromAttr();
  try {
    var am = localStorage.getItem("macrodash_apimode");
    if (am === "web" || am === "jes" || am === "compute") apiMode = am;
  } catch (e) {}
  var runAsTask = attr3("runAsTask") !== false; // default ON (web mode only)
  try {
    var rt = localStorage.getItem("macrodash_runastask");
    if (rt !== null) runAsTask = rt === "true";
  } catch (e) {}

  /* the configure service rewrites index.html itself, flipping this
     attribute - so the page knows synchronously whether it is configured,
     without waiting for a getConfig round trip. */
  var configured = !!(el && el.getAttribute("configured") === "true");
  /* The mock/browser build ships <meta name="sasjs-host" content="browser">.  It is
     served from a folder, so no configure service can re-stamp this page and the
     browser has to keep the record itself.  On a stamped target the attribute is
     the deployment's word: a redeploy that resets it to "false" must be believed,
     or a returning visitor is locked out of setup against an estate that has none
     (game.js greys the configurator once configured). */
  var browserHost = false;
  try {
    var hostMeta = document.querySelector('meta[name="sasjs-host"]');
    browserHost = !!(hostMeta && hostMeta.getAttribute("content") === "browser");
  } catch (e) {}
  var ready = null; // resolves once the remembered flag has been checked
  if (!configured && browserHost) {
    try {
      configured = localStorage.getItem("macrodash_configured") === "true";
    } catch (e) {}
    /* a cleared mock site (window.SASjsMock.reset(), the host's Clear button, or
       a drive emptied by hand) holds no <apploc>/settings.json, so a remembered
       flag would outlive the state it describes: drop it and let setup open */
    if (configured) ready = reconcileConfiguredFlag();
  }

  /* The check is asynchronous (one IndexedDB round trip), and the app reads
     isConfigured() at start-up - so it is exposed as a promise the caller waits
     on.  Otherwise the clear lands after the app has already decided, and a
     cleared site stays locked out of setup. */
  function reconcileConfiguredFlag() {
    return new Promise(function (resolve) {
      var tries = 0;
      (function poll() {
        var mock = window.SASjsMock;
        if (!mock || !mock.readAll) {
          if (++tries < 20) { setTimeout(poll, 250); return; }
          resolve();
          return;
        }
        mock.readAll().then(function (files) {
          var has = false;
          for (var k in (files || {})) {
            if (/\/settings\.json$/.test(k)) { has = true; break; }
          }
          if (!has) {
            configured = false;
            try { localStorage.removeItem("macrodash_configured"); } catch (e) {}
          }
          resolve();
        }).catch(function () { resolve(); });
      })();
    });
  }

  /* LAZY adapter load: sasjs.js is a big UMD bundle and a blocking
     <script src> tag delayed the title screen by seconds on slow
     connections.  It is injected only when a backend call actually
     happens (same-origin, so CSP-safe under script-src 'self'). */
  var sasjs = null;
  var adapterPromise = null;

  /* the defer'd adapter tag carries the build-rewritten (absolute on Viya
     JES) URL.  We run during document parsing, before deferred scripts
     execute - remove it so the bundle only ever loads/executes on demand. */
  var adapterTag = document.getElementById("sasjs-adapter");
  var adapterSrc = (adapterTag && adapterTag.getAttribute("src")) || "sasjs.js";
  if (adapterTag && adapterTag.parentNode) adapterTag.parentNode.removeChild(adapterTag);

  function loadAdapter() {
    if (adapterPromise) return adapterPromise;
    adapterPromise = new Promise(function (resolve) {
      if (window.SASjs) { resolve(true); return; }
      var s = document.createElement("script");
      s.src = adapterSrc;
      s.onload = function () { resolve(true); };
      s.onerror = function () { resolve(false); };
      document.head.appendChild(s);
    });
    return adapterPromise;
  }

  function buildAdapter() {
    try {
      sasjs = new window.SASjs.default({
        serverUrl: (el && el.getAttribute("serverUrl")) || undefined,
        appLoc: (el && el.getAttribute("appLoc")) || "/Public/app/macrodash",
        serverType: serverType,
        // user-picked (localStorage) wins; otherwise the attribute stamped
        // into this page by the configure service
        contextName: contextName || (el && el.getAttribute("contextName")) || undefined, // Viya only
        // three-state: web -> undefined, jes -> false, compute -> true
        useComputeApi: serverType !== "SASVIYA" || apiMode === "web"
          ? undefined : apiMode === "compute",
        // runAsTask only applies to the JES web approach
        runAsTask: serverType === "SASVIYA" && apiMode === "web" && runAsTask
          ? true : undefined,
        debug: debug
      });
      if (sasjs && sasjs.setDebugState) sasjs.setDebugState(debug);
    } catch (e) {
      sasjs = null;
    }
  }

  function withAdapter(cb) {
    if (sasjs) { cb(sasjs); return; }
    loadAdapter().then(function (ok) {
      if (!ok || !window.SASjs) { cb(null); return; }
      buildAdapter();
      cb(sasjs);
    });
  }

  /* hard timeout on every backend call: when the server is down (or the
     network drops), XHRs to it hang until the TCP timeout (minutes), which
     would leave the UI waiting.  A hung request degrades to local mode.
     On Viya a request spins up a compute session, which can take a minute
     or more on a cold estate - 5s would declare every call dead.  configure
     (folder validation + Drive rewrites) gets even longer. */
  var REQUEST_TIMEOUT_MS = serverType === "SASVIYA" ? 120000 : 5000;
  var CONFIGURE_TIMEOUT_MS = serverType === "SASVIYA" ? 300000 : 30000;

  /* adapter.request() resolves with the webout JSON already unwrapped -
   * tables are arrays of row objects directly on it (including a table
   * named `result`). */
  function call(service, data, cb, timeoutMs) {
    withAdapter(function (a) {
      if (!a) { cb(null); return; }
      var done = false;
      var timer = setTimeout(function () {
        done = true;
        cb(null);
      }, timeoutMs || REQUEST_TIMEOUT_MS);
      a.request("services/common/" + service, data)
        .then(function (res) {
          if (done) return;
          clearTimeout(timer);
          /* debug is ON, so the adapter keeps a per-request debug log
             accessible via getSasRequests() (the DC pattern).  The log
             lives there as `logFile` - capture it for the matching service
             so callers (configure) can offer a download link. */
          var saslog = "";
          try {
            var reqs = a.getSasRequests && a.getSasRequests();
            if (reqs && reqs.length) {
              var link = "services/common/" + service;
              var match = null;
              for (var i = reqs.length - 1; i >= 0; i--) {
                if (reqs[i] && reqs[i].serviceLink === link) { match = reqs[i]; break; }
              }
              if (match && typeof match.logFile === "string") saslog = match.logFile;
            }
          } catch (e) {}
          /* Viya wraps the webout JSON in a `result` property; SASjs server
             gives the tables directly.  Unwrap only when on Viya - a table
             or property actually NAMED `result` must pass through untouched. */
          if (serverType === "SASVIYA" && res && res.result &&
              typeof res.result === "object" &&
              !Array.isArray(res.result)) res = res.result;
          if (saslog) {
            if (typeof res === "object" && res !== null) res.log = saslog;
            else res = { result: res, log: saslog };
          }
          cb(res || null);
        })
        .catch(function () {
          if (done) return;
          clearTimeout(timer);
          /* even on failure, try to surface the SAS log so the user can
             diagnose (debug is ON - the adapter keeps logFile) */
          var saslog = "";
          try {
            var reqs = a.getSasRequests && a.getSasRequests();
            if (reqs && reqs.length) {
              var link = "services/common/" + service;
              var match = null;
              for (var i = reqs.length - 1; i >= 0; i--) {
                if (reqs[i] && reqs[i].serviceLink === link) { match = reqs[i]; break; }
              }
              if (match && typeof match.logFile === "string") saslog = match.logFile;
            }
          } catch (e) {}
          cb(saslog ? { log: saslog, error: true } : null);
        });
    });
  }

  /* Viya REST helper: the adapter exposes no public API for contexts or
     identities, so we hit the endpoints directly.  Same-origin when
     streamed by the SAS Job Execution web app (cookie auth), so
     'same-origin' credentials suffice and CSP (connect-src 'self') is
     untouched. */
  /* metadata calls (contexts list + one detail per context) can total
     several MB over a slow link - 5s truncates them mid-JSON */
  var META_TIMEOUT_MS = 30000;

