    getScores: function (cb) {
      call("getscores", null, function (j) {
        cb(j && j.scores ? j.scores : []);
      });
    },
    saveScore: function (entry, cb) {
      call("savescore", { savescore: [entry] }, function (j) {
        cb(j ? { scores: j.scores || [], rank: j.result ? j.result[0].RANK : null } : null);
      });
    }
  };
})();

/* Macro Dash - on-screen gameboy pad.
 * Binds the buttons in index.html (#pad-left/right/jump/run/start) to the
 * game's input via window.MACRODASH_PRESS (exposed by game.js), so pad
 * presses are indistinguishable from real key presses - including audio
 * unlock on first touch.  Mouse and touch both work; multi-touch is fine
 * because each button tracks its own press state.
 */
(function () {
  "use strict";

  var press = window.MACRODASH_PRESS;
  if (!press) return;

  function bind(id, code) {
    var el = document.getElementById(id);
    if (!el) return;
    var held = false;

    function down(e) {
      e.preventDefault();
      if (held) return;
      held = true;
      el.classList.add("held");
      press(code, true);
    }
    function up(e) {
      if (e) e.preventDefault();
      if (!held) return;
      held = false;
      el.classList.remove("held");
      press(code, false);
    }

    el.addEventListener("mousedown", down);
    el.addEventListener("touchstart", down, { passive: false });
    el.addEventListener("mouseup", up);
    el.addEventListener("mouseleave", up);
    el.addEventListener("touchend", up);
    el.addEventListener("touchcancel", up);
    // releasing the mouse anywhere should not leave a button stuck down
    window.addEventListener("blur", up);
  }

  // brand header: click returns to the title screen (the "homepage")
  var brand = document.getElementById("brand");
  if (brand && window.MACRODASH_FORCE) {
    brand.addEventListener("click", function (e) {
      e.preventDefault();
      window.MACRODASH_FORCE("title");
    });
  }

  bind("pad-left", "ArrowLeft");
  bind("pad-right", "ArrowRight");
  bind("pad-up", "Space");       // up arrow = jump

  /* RUN doubles as action button: on title/win/dead/finale screens it acts
     as ENTER (start / retry / next level); on the setup screen it saves
     (the text-entry handler consumes that Enter); during play it is
     hold-to-run. */
  var getState = window.MACRODASH_STATE || function () { return "play"; };
  var runBtn = document.getElementById("pad-run");
  if (runBtn) {
    var runHeld = false;
    function runDown(e) {
      e.preventDefault();
      if (runHeld) return;
      runHeld = true;
      runBtn.classList.add("held");
      var s = getState();
      if (s !== "play" && s !== "pause") {
        // title, dead, win, winname, config, complete, board: RUN = ENTER
        document.dispatchEvent(new KeyboardEvent("keydown", { code: "Enter" }));
      } else {
        press("ShiftLeft", true);
      }
    }
    function runUp(e) {
      if (e) e.preventDefault();
      if (!runHeld) return;
      runHeld = false;
      runBtn.classList.remove("held");
      press("ShiftLeft", false);
    }
    runBtn.addEventListener("mousedown", runDown);
    runBtn.addEventListener("touchstart", runDown, { passive: false });
    runBtn.addEventListener("mouseup", runUp);
    runBtn.addEventListener("mouseleave", runUp);
    runBtn.addEventListener("touchend", runUp);
    runBtn.addEventListener("touchcancel", runUp);
    window.addEventListener("blur", runUp);
  }
})();

/* Macro Dash - tiny canvas platformer engine (CSP-safe: no inline styles,
 * canvas sized via width/height attributes). */
(function () {
  "use strict";

  var TILE = 32;

  function createEngine(container, levelRows, opts) {
    var cols = 0;
    levelRows.forEach(function (r) { cols = Math.max(cols, r.length); });
    var rows = levelRows.length;

    var canvas = document.createElement("canvas");
    canvas.width = opts.viewWidth;
    canvas.height = rows * TILE;
    container.appendChild(canvas);
    var g = canvas.getContext("2d");

    function tileAt(col, row) {
      if (row < 0 || row >= rows) return ".";
      if (col < 0 || col >= cols) return "#"; // walls at edges
      var ch = levelRows[row][col];
      return ch === undefined ? "." : ch;
    }

    function solidAt(col, row) {
      var t = tileAt(col, row);
      return t === "#" || t === "=";
    }

    // AABB vs tilemap resolution
    function moveAndCollide(e) {
      // horizontal
      e.x += e.vx;
      var left = Math.floor(e.x / TILE);
      var right = Math.floor((e.x + e.w - 1) / TILE);
      var top = Math.floor(e.y / TILE);
      var bottom = Math.floor((e.y + e.h - 1) / TILE);
      for (var r = top; r <= bottom; r++) {
        if (e.vx > 0 && solidAt(right, r)) { e.x = right * TILE - e.w; e.vx = 0; e.hitWall = 1; }
        if (e.vx < 0 && solidAt(left, r)) { e.x = (left + 1) * TILE; e.vx = 0; e.hitWall = -1; }
      }
      // vertical
      e.y += e.vy;
      e.onGround = false;
      left = Math.floor(e.x / TILE);
      right = Math.floor((e.x + e.w - 1) / TILE);
      top = Math.floor(e.y / TILE);
      bottom = Math.floor((e.y + e.h - 1) / TILE);
      for (var c = left; c <= right; c++) {
        if (e.vy > 0 && solidAt(c, bottom)) { e.y = bottom * TILE - e.h; e.vy = 0; e.onGround = true; }
        if (e.vy < 0 && solidAt(c, top)) { e.y = (top + 1) * TILE; e.vy = 0; }
      }
    }

    function overlap(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    var api = {
      TILE: TILE,
      canvas: canvas,
      ctx: g,
      viewWidth: opts.viewWidth,
      tileAt: tileAt,
      solidAt: solidAt,
      moveAndCollide: moveAndCollide,
      overlap: overlap,
      cameraX: function (targetX) {
        var cam = targetX - opts.viewWidth / 2;
        return Math.max(0, Math.min(cam, cols * TILE - opts.viewWidth));
      },
      // swap in a new level map (same TILE size; canvas height adjusts)
      setLevel: function (newRows) {
        levelRows = newRows;
        cols = 0;
        newRows.forEach(function (r) { cols = Math.max(cols, r.length); });
        rows = newRows.length;
        canvas.height = rows * TILE;
        api.worldWidth = cols * TILE;
        api.worldHeight = rows * TILE;
      }
    };
    api.worldWidth = cols * TILE;
    api.worldHeight = rows * TILE;
    return api;
  }

  window.MACRODASH_ENGINE = { create: createEngine };
})();

/* Macro Dash - game logic.  Level 1: The WORK Library; Level 2: Batch at
 * Midnight.  Levels advance on the win screen (ENTER), per-level bests are
 * kept in localStorage. */
(function () {
  "use strict";

  var LEVELS = window.MACRODASH_LEVELS;
  var LEVEL_NAMES = window.MACRODASH_LEVEL_NAMES || [];
  var levelIdx = 0;
  var level = LEVELS[levelIdx];
  var audio = window.MACRODASH_AUDIO;
  var eng = window.MACRODASH_ENGINE.create(document.getElementById("game"), level, {
    viewWidth: 800
  });
  var TILE = eng.TILE;
  var ctx = eng.ctx;

  var GRAVITY = 0.8;    // snappier, less floaty arcs (Macro Dash tuning)
  var WALK = 5.5;
  var RUN = 11;
  var JUMP = -12.75;   // ~3 tiles + margin (~102px vs 96px needed)
  var JUMP_HI = -16.25; // ~5 tiles + margin (~166px vs 160px needed)
  var BOOST_FRAMES = 720; // 12s of FORMAT power

  // ---- parse level into entities ----
  /* A game is one RUN across all levels: amps, health, error/warning counts
   * and the speedrun clock carry over; the score is only finalised when the
   * run ENDS (death, or the final portal).  init(true) starts a fresh run;
   * init(false) advances to the next level keeping the run state. */
