  window.MACRODASH_CONFIG_FIELD = function () { return configField; }; // test hook
  window.MACRODASH_VIYAAUTH = function () { return viyaAuth; }; // test hook
  /* test hook: render the full Viya configurator locally (no SAS calls) -
